import { useState, useMemo, useEffect, useRef } from "react";
import jsPDF from "jspdf";
import html2canvas from "html2canvas";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from "recharts";
import { db } from "./firebase";
import { doc, setDoc, onSnapshot } from "firebase/firestore";

const DAYS_ES = ["Dom","Lun","Mar","Mié","Jue","Vie","Sáb"];
const MONTHS_ES = ["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
function getTodayStr() { return new Date().toISOString().split("T")[0]; }
function getWeekDates(dateStr) {
  const d = new Date(dateStr+"T12:00:00"); const diff = d.getDate()-d.getDay();
  return Array.from({length:7},(_,i)=>{const nd=new Date(d);nd.setDate(diff+i);return nd.toISOString().split("T")[0];});
}

const DEFAULT_VEHICLES = [
  "SON589","XGD950","TUL404","TFP410","SQY053","TUL416","XVJ448","SKP285",
  "SWQ606","NUU698","KSK012","TLP792","JYN900","SOD674","SKV787","YHK173"
].map(plate=>({plate, available:true, owner:"", replacedBy:null}));

const C = {
  bg:"#0f1117", surface:"#1a1d27", card:"#21253a",
  blue:"#1a56c4", yellowGreen:"#b5c832",
  green:"#4ade80", red:"#f87171", orange:"#fb923c",
  text:"#e8eaf6", muted:"#7c8099", border:"#2d3154",
};

// --- Embedded assets (base64) ---
const LOGO_B64 = "data:image/png;base64,";
const FIRMA_B64 = "data:image/png;base64,";

const CanavenLogo = () => (
  <div style={{display:"flex",alignItems:"center",gap:8}}>
    <svg width="44" height="28" viewBox="0 0 88 56" fill="none" xmlns="http://www.w3.org/2000/svg">
      <rect x="2" y="6" width="52" height="26" rx="13" fill="none" stroke={C.blue} strokeWidth="3"/>
      <rect x="54" y="14" width="24" height="18" rx="3" fill="none" stroke={C.blue} strokeWidth="3"/>
      <line x1="54" y1="23" x2="2" y2="23" stroke={C.blue} strokeWidth="1.5"/>
      <circle cx="18" cy="40" r="7" fill="none" stroke={C.blue} strokeWidth="3"/>
      <circle cx="18" cy="40" r="2.5" fill={C.blue}/>
      <circle cx="52" cy="40" r="7" fill="none" stroke={C.blue} strokeWidth="3"/>
      <circle cx="52" cy="40" r="2.5" fill={C.blue}/>
      <line x1="0" y1="48" x2="82" y2="48" stroke={C.yellowGreen} strokeWidth="2.5"/>
    </svg>
    <div style={{display:"flex",flexDirection:"column",lineHeight:1}}>
      <div style={{fontFamily:"'Arial Black',Arial,sans-serif",fontWeight:900,fontSize:17,color:C.blue,letterSpacing:"0.04em"}}>CANAVEN</div>
      <div style={{fontFamily:"Arial,sans-serif",fontSize:8,color:C.yellowGreen,letterSpacing:"0.05em",marginTop:3}}>Transportes de Colombia SAS</div>
    </div>
  </div>
);

function load(key,fb){try{const v=localStorage.getItem(key);return v?JSON.parse(v):fb;}catch{return fb;}}
function save(key,val){try{localStorage.setItem(key,JSON.stringify(val));}catch{}}

export default function App() {
  const [tab, setTab] = useState("schedule");
  const [vehicles, setVehicles] = useState(DEFAULT_VEHICLES);
  const [schedules, setSchedules] = useState({});
  const [selectedDate, setSelectedDate] = useState(getTodayStr());
  const [reportView, setReportView] = useState("weekly");
  const [selectedPlates, setSelectedPlates] = useState([]);
  const [syncing, setSyncing] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const [replaceInput, setReplaceInput] = useState({});
  const [editVehicle, setEditVehicle] = useState(null); // {plate, newPlate, owner}
  const [pdfFrom, setPdfFrom] = useState(getTodayStr());
  const [pdfTo, setPdfTo] = useState(getTodayStr());
  const [pdfObs, setPdfObs] = useState("");
  const [csvFrom, setCsvFrom] = useState(getTodayStr());
  const [csvTo, setCsvTo] = useState(getTodayStr());
  const [generatingPdf, setGeneratingPdf] = useState(false);
  const [showPdfPreview, setShowPdfPreview] = useState(false);
  const [showPdfModal, setShowPdfModal] = useState(false);
  const pdfRef = useRef(null);
  // Load confirm modal
  const [confirmModal, setConfirmModal] = useState(null); // {plate}
  const [loadForm, setLoadForm] = useState({fecha:"", guia:"", volumen:""});

  // Auth
  const [authed, setAuthed] = useState(()=>!!sessionStorage.getItem("canaven_role"));
  const [role, setRole] = useState(()=>sessionStorage.getItem("canaven_role")||"");
  const [pinInput, setPinInput] = useState("");
  const [pinError, setPinError] = useState(false);
  const PIN_ADMIN="2025"; const PIN_VIEWER="1111";
  const isAdmin = role==="admin";
  const handleLogin = () => {
    if(pinInput===PIN_ADMIN){sessionStorage.setItem("canaven_role","admin");setRole("admin");setAuthed(true);setPinError(false);}
    else if(pinInput===PIN_VIEWER){sessionStorage.setItem("canaven_role","viewer");setRole("viewer");setAuthed(true);setPinError(false);}
    else{setPinError(true);setPinInput("");}
  };

  const badge = (ok)=>({display:"inline-flex",alignItems:"center",gap:4,padding:"3px 9px",borderRadius:20,fontSize:10,fontWeight:700,letterSpacing:"0.07em",textTransform:"uppercase",background:ok?C.green+"22":C.red+"22",color:ok?C.green:C.red,border:`1px solid ${ok?C.green+"55":C.red+"55"}`});

  // Firebase sync with timeout fallback
  useEffect(()=>{
    // Fallback: if Firebase takes too long, load anyway
    const timeout = setTimeout(()=>{
      setLoaded(true);
    }, 4000);

    let unsub;
    try {
      unsub = onSnapshot(doc(db,"canaven","data"),(snap)=>{
        clearTimeout(timeout);
        if(snap.exists()){
          const data=snap.data();
          if(data.vehicles)setVehicles(data.vehicles);
          if(data.schedules)setSchedules(data.schedules);
        }
        setLoaded(true);
      }, (error)=>{
        // Firebase error - load with defaults
        console.error("Firebase error:", error);
        clearTimeout(timeout);
        setLoaded(true);
      });
    } catch(e) {
      console.error("Firebase init error:", e);
      clearTimeout(timeout);
      setLoaded(true);
    }
    return ()=>{ clearTimeout(timeout); if(unsub) unsub(); };
  },[]);

  const saveToFirestore = async(v,s)=>{
    setSyncing(true);
    try{await setDoc(doc(db,"canaven","data"),{vehicles:v,schedules:s,updatedAt:new Date().toISOString()});}
    catch(e){console.error(e);}
    setSyncing(false);
  };
  const updateVehicles=(nv)=>{setVehicles(nv);saveToFirestore(nv,schedules);};
  const updateSchedules=(ns)=>{setSchedules(ns);saveToFirestore(vehicles,ns);};

  // Fleet
  const addVehicle=()=>{
    const p=document.getElementById("new-plate-input")?.value?.trim()?.toUpperCase();
    if(!p||vehicles.find(v=>v.plate===p))return;
    const nv=[...vehicles,{plate:p,available:true,owner:"",replacedBy:null}];
    updateVehicles(nv);
    document.getElementById("new-plate-input").value="";
  };
  const removeVehicle=(plate)=>updateVehicles(vehicles.filter(v=>v.plate!==plate));
  const toggleAvailability=(plate)=>updateVehicles(vehicles.map(v=>v.plate===plate?{...v,available:!v.available}:v));

  const saveEditVehicle=()=>{
    if(!editVehicle)return;
    const newPlate=(editVehicle.newPlate||"").trim().toUpperCase()||editVehicle.plate;
    const nv=vehicles.map(v=>v.plate===editVehicle.plate?{...v,plate:newPlate,owner:editVehicle.owner}:v);
    // also update schedules if plate changed
    if(newPlate!==editVehicle.plate){
      const ns={};
      Object.entries(schedules).forEach(([date,ds])=>{ns[date]=ds.map(s=>s.plate===editVehicle.plate?{...s,plate:newPlate}:s);});
      updateVehicles(nv);updateSchedules(ns);
    } else {updateVehicles(nv);}
    setEditVehicle(null);
  };

  const applyReplacement=(originalPlate)=>{
    const newPlate=(replaceInput[originalPlate]||"").trim().toUpperCase();
    if(!newPlate||newPlate===originalPlate)return;
    let nv=vehicles.map(v=>v.plate===originalPlate?{...v,available:false,replacedBy:newPlate}:v);
    if(!nv.find(v=>v.plate===newPlate)){
      const idx=nv.findIndex(v=>v.plate===originalPlate);
      nv.splice(idx+1,0,{plate:newPlate,available:true,owner:"",replacedBy:null});
    }
    updateVehicles([...nv]);
    setReplaceInput(p=>({...p,[originalPlate]:""}));
  };
  const clearReplacement=(originalPlate)=>{
    const v=vehicles.find(p=>p.plate===originalPlate);
    if(!v||!v.replacedBy)return;
    const nv=vehicles.filter(p=>p.plate!==v.replacedBy).map(p=>p.plate===originalPlate?{...p,available:true,replacedBy:null}:p);
    updateVehicles(nv);
  };

  // Schedule
  const scheduleForDate=schedules[selectedDate]||[];
  const alreadyScheduled=scheduleForDate.map(v=>v.plate);
  const notYetScheduled=vehicles.filter(v=>v.available&&!alreadyScheduled.includes(v.plate));
  const toggleSelectPlate=(plate)=>setSelectedPlates(prev=>prev.includes(plate)?prev.filter(p=>p!==plate):[...prev,plate]);
  const selectAll=()=>setSelectedPlates(notYetScheduled.map(v=>v.plate));
  const clearSelection=()=>setSelectedPlates([]);

  const addSelectedToSchedule=()=>{
    if(!selectedPlates.length)return;
    const existing=schedules[selectedDate]||[];
    const toAdd=selectedPlates.filter(plate=>!existing.find(e=>e.plate===plate))
      .map(plate=>({plate,loaded:false,loadedTime:null,loadDate:"",guia:"",volumen:"",observaciones:""}));
    updateSchedules({...schedules,[selectedDate]:[...existing,...toAdd]});
    setSelectedPlates([]);
  };
  const removeFromSchedule=(plate)=>updateSchedules({...schedules,[selectedDate]:(schedules[selectedDate]||[]).filter(v=>v.plate!==plate)});

  const openConfirmLoad=(plate)=>{
    const existing=(schedules[selectedDate]||[]).find(v=>v.plate===plate);
    if(existing?.loaded){
      // toggle off directly
      const day=[...(schedules[selectedDate]||[])];
      const idx=day.findIndex(v=>v.plate===plate);
      day[idx]={...day[idx],loaded:false,loadedTime:null,loadDate:"",guia:"",volumen:""};
      updateSchedules({...schedules,[selectedDate]:day});
    } else {
      setLoadForm({fecha:getTodayStr(),guia:"",volumen:""});
      setConfirmModal({plate});
    }
  };
  const confirmLoad=()=>{
    if(!confirmModal)return;
    const day=[...(schedules[selectedDate]||[])];
    const idx=day.findIndex(v=>v.plate===confirmModal.plate);
    if(idx===-1)return;
    day[idx]={...day[idx],loaded:true,loadedTime:new Date().toLocaleTimeString("es-CO",{hour:"2-digit",minute:"2-digit"}),
      loadDate:loadForm.fecha,guia:loadForm.guia,volumen:loadForm.volumen};
    updateSchedules({...schedules,[selectedDate]:day});
    setConfirmModal(null);
  };

  const updateObservaciones=(plate,value)=>{
    const day=[...(schedules[selectedDate]||[])];
    const idx=day.findIndex(v=>v.plate===plate);
    if(idx===-1)return;
    day[idx]={...day[idx],observaciones:value};
    updateSchedules({...schedules,[selectedDate]:day});
  };

  // WhatsApp
  const buildWhatsAppText=()=>{
    const d=new Date(selectedDate+"T12:00:00");
    const dateLabel=`${DAYS_ES[d.getDay()]} ${d.getDate()} de ${MONTHS_ES[d.getMonth()]} ${d.getFullYear()}`;
    const lines=[`🚛 *CANAVEN - Programación Vehicular*`,`📅 ${dateLabel}`,``,`*Vehículos Programados:*`];
    scheduleForDate.forEach((v,i)=>{
      const status=v.loaded?`✅ Cargado${v.loadedTime?" · "+v.loadedTime:""}${v.guia?" · Guía: "+v.guia:""}${v.volumen?" · Vol: "+v.volumen:""}`:` ⏳ Programado`;
      const obs=v.observaciones?` · 📝 ${v.observaciones}`:"";
      lines.push(`${i+1}. *${v.plate}* —${status}${obs}`);
    });
    lines.push(``,`📋 Total: ${scheduleForDate.length} · ✅ Cargados: ${scheduleForDate.filter(v=>v.loaded).length}`);
    return lines.join("\n");
  };
  const copyMessage=()=>navigator.clipboard.writeText(buildWhatsAppText()).catch(()=>{});
  const sendWhatsApp=()=>window.open(`https://chat.whatsapp.com/LCkWONNBkq41X0mWV9feOF?text=${encodeURIComponent(buildWhatsAppText())}`,"_blank");

  // CSV
  const downloadCSV=()=>{
    const rows=[["Fecha","Dia","Placa","Propietario","Estado","Hora Cargue","Fecha Cargue","No. Guia","Volumen","Observaciones"]];
    const allDates=Object.keys(schedules).sort();
    const from=new Date(csvFrom+"T00:00:00");
    const to=new Date(csvTo+"T23:59:59");
    const filtered=allDates.filter(d=>{const dt=new Date(d+"T12:00:00");return dt>=from&&dt<=to;});
    filtered.forEach(date=>{
      const d=new Date(date+"T12:00:00");
      const dayName=DAYS_ES[d.getDay()];
      (schedules[date]||[]).forEach(v=>{
        if(v.loaded){
          const veh=vehicles.find(x=>x.plate===v.plate)||{};
          rows.push([date,dayName,v.plate,veh.owner||"",v.loaded?"Cargado":"Pendiente",v.loadedTime||"",v.loadDate||"",v.guia||"",v.volumen||"",v.observaciones||""]);
        }
      });
    });
    const csv=rows.map(r=>r.map(c=>`"${c}"`).join(",")).join("\n");
    const blob=new Blob(["\uFEFF"+csv],{type:"text/csv;charset=utf-8;"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;a.download=`canaven_${csvFrom}_${csvTo}.csv`;a.click();
    URL.revokeObjectURL(url);
  };

  // PDF
  const generatePDF = async () => {
    setShowPdfPreview(true);
    // Wait for render
    await new Promise(r => setTimeout(r, 500));
    setGeneratingPdf(true);
    try {
      const el = pdfRef.current;
      if (!el) return;
      const canvas = await html2canvas(el, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: "#ffffff",
        logging: false,
      });
      const imgData = canvas.toDataURL("image/png");
      const pdf = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4" });
      const pdfW = pdf.internal.pageSize.getWidth();
      const pdfH = pdf.internal.pageSize.getHeight();
      const imgW = canvas.width;
      const imgH = canvas.height;
      const ratio = pdfW / imgW;
      const scaledH = imgH * ratio;
      let y = 0;
      let remaining = scaledH;
      while (remaining > 0) {
        const pageH = Math.min(pdfH, remaining);
        pdf.addImage(imgData, "PNG", 0, -y, pdfW, scaledH);
        remaining -= pdfH;
        y += pdfH;
        if (remaining > 0) pdf.addPage();
      }
      pdf.save("Informe_Canaven_" + pdfFrom + "_" + pdfTo + ".pdf");
    } catch (e) {
      console.error(e);
      alert("Error generando PDF: " + e.message);
    }
    setGeneratingPdf(false);
    setShowPdfPreview(false);
  };


  // Reports data
  const weekDates=useMemo(()=>getWeekDates(selectedDate),[selectedDate]);
  const currentMonth=useMemo(()=>new Date(selectedDate+"T12:00:00").getMonth(),[selectedDate]);
  const currentYear=useMemo(()=>new Date(selectedDate+"T12:00:00").getFullYear(),[selectedDate]);
  const weeklyData=useMemo(()=>weekDates.map(date=>{const ds=schedules[date]||[];const d=new Date(date+"T12:00:00");return{name:DAYS_ES[d.getDay()],programados:ds.length,cargados:ds.filter(v=>v.loaded).length};}), [schedules,weekDates]);
  const monthlyData=useMemo(()=>{const byDay={};Object.entries(schedules).forEach(([date,ds])=>{const d=new Date(date+"T12:00:00");if(d.getMonth()===currentMonth&&d.getFullYear()===currentYear)byDay[d.getDate()]={name:`${d.getDate()}`,programados:ds.length,cargados:ds.filter(v=>v.loaded).length};});return Object.values(byDay).sort((a,b)=>parseInt(a.name)-parseInt(b.name));},[schedules,currentMonth,currentYear]);
  const vehicleTotals=useMemo(()=>{const t={};vehicles.forEach(v=>{t[v.plate]={scheduled:0,loaded:0};});Object.values(schedules).forEach(ds=>ds.forEach(v=>{if(!t[v.plate])t[v.plate]={scheduled:0,loaded:0};t[v.plate].scheduled++;if(v.loaded)t[v.plate].loaded++;}));return t;},[schedules,vehicles]);
  const reportData=reportView==="weekly"?weeklyData:monthlyData;

  const TABS=[{id:"fleet",icon:"🚗",label:"Flota"},{id:"schedule",icon:"📅",label:"Programar"},{id:"reports",icon:"📊",label:"Informes"}];

  // PIN screen FIRST (so user always sees login, not black screen)
  if(!authed)return(
    <div style={{minHeight:"100vh",background:C.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",padding:"24px"}}>
      <style>{`@keyframes shake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}`}</style>
      <div style={{width:"100%",maxWidth:320}}>
        <div style={{display:"flex",justifyContent:"center",marginBottom:32}}><CanavenLogo/></div>
        <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:20,padding:"32px 24px",textAlign:"center"}}>
          <div style={{fontSize:44,marginBottom:12}}>🔒</div>
          <div style={{fontSize:18,fontWeight:800,color:C.text,marginBottom:6}}>Acceso Protegido</div>
          <div style={{fontSize:13,color:C.muted,marginBottom:8}}>Ingresa tu PIN para continuar</div>
          <div style={{display:"flex",gap:8,justifyContent:"center",marginBottom:20}}>
            <span style={{background:C.blue+"22",color:C.blue,border:`1px solid ${C.blue}44`,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>⚙️ Admin</span>
            <span style={{background:C.green+"22",color:C.green,border:`1px solid ${C.green}44`,borderRadius:20,padding:"3px 10px",fontSize:11,fontWeight:700}}>👁️ Visitante</span>
          </div>
          <div style={{display:"flex",justifyContent:"center",gap:12,marginBottom:24}}>
            {[0,1,2,3].map(i=>(<div key={i} style={{width:14,height:14,borderRadius:"50%",background:pinInput.length>i?C.blue:C.border,transition:"background 0.15s"}}/>))}
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:10,marginBottom:16}}>
            {["1","2","3","4","5","6","7","8","9","","0","⌫"].map((k,i)=>(
              <button key={i} onClick={()=>{if(k==="⌫"){setPinInput(p=>p.slice(0,-1));setPinError(false);}else if(k===""||pinInput.length>=4)return;else setPinInput(p=>p+k);}}
                style={{background:k===""?"transparent":pinError?C.red+"22":C.surface,border:`1px solid ${k===""?"transparent":pinError?C.red+"55":C.border}`,borderRadius:12,padding:"16px 0",fontSize:20,fontWeight:700,color:k==="⌫"?C.muted:C.text,cursor:k===""?"default":"pointer"}} disabled={k===""}>
                {k}
              </button>
            ))}
          </div>
          {pinError&&<div style={{color:C.red,fontSize:13,fontWeight:600,marginBottom:12}}>PIN incorrecto.</div>}
          <button onClick={handleLogin} disabled={pinInput.length<4} style={{width:"100%",background:pinInput.length===4?C.blue:C.border,color:pinInput.length===4?"#fff":C.muted,border:"none",borderRadius:12,padding:"14px 0",fontSize:16,fontWeight:700,cursor:pinInput.length===4?"pointer":"not-allowed"}}>Ingresar</button>
        </div>
        <div style={{textAlign:"center",marginTop:20,fontSize:11,color:C.muted}}>CANAVEN Transportes de Colombia SAS</div>
      </div>
    </div>
  );

  // Loading screen (after PIN so login always shows first)
  if(!loaded)return(
    <div style={{minHeight:"100vh",background:C.bg,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:16}}>
      <CanavenLogo/>
      <div style={{color:C.muted,fontSize:13,marginTop:8}}>Cargando datos...</div>
      <div style={{width:40,height:40,border:`3px solid ${C.border}`,borderTop:`3px solid ${C.blue}`,borderRadius:"50%",animation:"spin 0.8s linear infinite"}}/>
      <style>{`@keyframes spin{to{transform:rotate(360deg);}}`}</style>
    </div>
  );

  // --- Build PDF report data ---
  const pdfReportData = useMemo(() => {
    const from = new Date(pdfFrom + "T12:00:00");
    const to   = new Date(pdfTo   + "T12:00:00");
    const days = [];
    let cur = new Date(from);
    while (cur <= to) {
      const ds = cur.toISOString().split("T")[0];
      const loaded = (schedules[ds] || []).filter(v => v.loaded).length;
      if (loaded > 0) {
        days.push({ label: cur.getDate()+"/"+(cur.getMonth()+1)+"/"+String(cur.getFullYear()).slice(2), val: loaded });
      }
      cur.setDate(cur.getDate() + 1);
    }
    const totalDays = days.reduce((s, d) => s + d.val, 0);
    const mmap = {};
    Object.entries(schedules).forEach(([date, ds]) => {
      const d = new Date(date + "T12:00:00");
      const key = d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0");
      if (!mmap[key]) mmap[key] = { label: MONTHS_ES[d.getMonth()].slice(0,3)+" "+d.getFullYear(), val: 0 };
      mmap[key].val += ds.filter(v => v.loaded).length;
    });
    const months = Object.entries(mmap).sort(([a],[b])=>a.localeCompare(b)).map(([,v])=>v).slice(-12);
    const vData = vehicles.map(v => {
      const ld = Object.entries(schedules)
        .filter(([date]) => { const d=new Date(date+"T12:00:00"); return d>=from&&d<=to; })
        .reduce((s,[,ds]) => { const f=ds.find(x=>x.plate===v.plate); return s+(f&&f.loaded?1:0); }, 0);
      return { plate: v.plate, val: ld, pct: totalDays>0?Math.round(ld/totalDays*100):0 };
    }).filter(d=>d.val>0).sort((a,b)=>b.val-a.val);
    return { days, months, vData, totalDays };
  }, [pdfFrom, pdfTo, schedules, vehicles]);

  const PdfBarChart = ({ data, color }) => {
    const W=460, H=150, PL=24, PB=40, PT=16, PR=6;
    const cW=W-PL-PR, cH=H-PT-PB;
    if (!data.length) return <div style={{color:"#999",textAlign:"center",padding:20}}>Sin datos</div>;
    const maxV = Math.max(...data.map(d=>d.val), 1);
    const bW = Math.max(6, Math.min(28, Math.floor(cW/data.length)-3));
    const gap = (cW - bW*data.length) / (data.length+1);
    return (
      <svg width={W} height={H} style={{overflow:"visible"}}>
        {[0,0.5,1].map(p => {
          const v2=Math.round(maxV*p); const y=PT+cH-Math.round(p*cH);
          return <g key={p}><line x1={PL} y1={y} x2={W-PR} y2={y} stroke="#ddd" strokeWidth="1"/><text x={PL-3} y={y+3} textAnchor="end" fontSize="8" fill="#aaa">{v2}</text></g>;
        })}
        <line x1={PL} y1={PT+cH} x2={W-PR} y2={PT+cH} stroke="#999" strokeWidth="1.5"/>
        {data.map((d,i) => {
          const x=PL+gap+i*(bW+gap);
          const bH=Math.max(2,Math.round(d.val/maxV*cH));
          const y=PT+cH-bH;
          const lx=x+bW/2, ly=PT+cH+8;
          return (
            <g key={i}>
              <rect x={x} y={y} width={bW} height={bH} fill={color} rx="2"/>
              <text x={x+bW/2} y={y-3} textAnchor="middle" fontSize="8" fontWeight="bold" fill="#333">{d.val}</text>
              <text transform={`rotate(-38,${lx},${ly})`} x={lx} y={ly} textAnchor="end" fontSize="7" fill="#666">{d.label}</text>
            </g>
          );
        })}
      </svg>
    );
  };

  const PdfPreview = () => {
    const { days, months, vData, totalDays } = pdfReportData;
    const fmt = dt => dt.getDate()+"/"+(dt.getMonth()+1)+"/"+dt.getFullYear();
    const today = fmt(new Date());
    const fromLbl = fmt(new Date(pdfFrom+"T12:00:00"));
    const toLbl   = fmt(new Date(pdfTo  +"T12:00:00"));
    const tableRows = days.map((d,i) => (
      <tr key={i}><td style={{border:"1px solid #ccc",padding:"4px 14px",textAlign:"center"}}>{d.label}</td><td style={{border:"1px solid #ccc",padding:"4px 14px",textAlign:"center",fontWeight:"bold"}}>{d.val}</td></tr>
    ));
    return (
      <div ref={pdfRef} style={{background:"#fff",color:"#222",fontFamily:"Arial,sans-serif",fontSize:11,padding:32,width:794,margin:"0 auto"}}>
        {/* Header */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:"2px solid #1a56c4",paddingBottom:10,marginBottom:18}}>
          <img src={"data:image/png;base64,"} style={{height:48,objectFit:"contain"}}/>
          <div style={{textAlign:"right",fontSize:10,color:"#555"}}>Informe generado: {today}</div>
        </div>
        {/* Title */}
        <h2 style={{textAlign:"center",fontSize:13,letterSpacing:1,margin:"0 0 14px",fontWeight:"bold"}}>INFORME OPERATIVO SEMANAL</h2>
        <p style={{marginBottom:6}}><strong>1. FECHA:</strong> {today}</p>
        {/* Activities */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>2. ACTIVIDADES:</p>
        <div style={{marginLeft:18,lineHeight:1.9,fontSize:10}}>
          {["Programación de vehículos diarios.","Seguimiento de GPS para asegurar cantidad de vehículos programados","Solicitud de documentos operativos a los propietarios","Comunicación con personal de Canacol para asegurar la actividad y cumplir la programación.","Reunión propietarios temas de facturación y pagos."].map((a,i)=>(
            <div key={i}>{i+1}. {a}</div>
          ))}
        </div>
        {/* Daily chart */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>3. INDICADORES: cargue de vehículos del {fromLbl} al {toLbl}</p>
        <div style={{border:"1px solid #ddd",borderRadius:4,padding:14,margin:"10px 0"}}>
          <div style={{textAlign:"center",fontWeight:"bold",fontSize:12,marginBottom:8}}>CARGUES POR DÍA</div>
          <PdfBarChart data={days} color="#1a56c4"/>
          <div style={{textAlign:"center",marginTop:4,fontSize:9,color:"#555"}}>■ CARGUES</div>
        </div>
        {/* Monthly chart */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>4. COMPARATIVO MENSUAL DE CARGUES</p>
        <div style={{border:"1px solid #ddd",borderRadius:4,padding:14,margin:"10px 0"}}>
          <div style={{textAlign:"center",fontWeight:"bold",fontSize:12,marginBottom:8}}>CARGUES POR MES</div>
          <PdfBarChart data={months} color="#b5c832"/>
          <div style={{textAlign:"center",marginTop:4,fontSize:9,color:"#555"}}>■ TOTAL CARGUES POR MES</div>
        </div>
        {/* Table */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>5. INDICADOR: DEL {fromLbl.toUpperCase()} A {toLbl.toUpperCase()}</p>
        <table style={{borderCollapse:"collapse",margin:"0 auto"}}>
          <thead><tr><th style={{background:"#1a56c4",color:"#fff",padding:"5px 20px",fontSize:11}}>DIA</th><th style={{background:"#1a56c4",color:"#fff",padding:"5px 20px",fontSize:11}}>VIAJES</th></tr></thead>
          <tbody>{tableRows}</tbody>
          <tfoot><tr><td style={{fontWeight:"bold",background:"#f0f0f0",border:"1px solid #ccc",padding:"5px 14px",textAlign:"center"}}>TOTAL</td><td style={{fontWeight:"bold",background:"#f0f0f0",border:"1px solid #ccc",padding:"5px 14px",textAlign:"center"}}>{totalDays}</td></tr></tfoot>
        </table>
        {/* Vehicle availability */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>6. DISPONIBILIDAD POR VEHÍCULO</p>
        <div style={{border:"1px solid #ddd",borderRadius:4,padding:14,margin:"10px 0"}}>
          <div style={{textAlign:"center",fontWeight:"bold",fontSize:12,marginBottom:8}}>% Participación de Cargues por Vehículo</div>
          {vData.map((v,i) => {
            const bc = v.pct>=20?"#4ade80":v.pct>=10?"#b5c832":"#1a56c4";
            return (
              <div key={i} style={{display:"flex",alignItems:"center",gap:8,marginBottom:6}}>
                <div style={{fontWeight:"bold",fontSize:10,width:70,flexShrink:0}}>{v.plate}</div>
                <div style={{flex:1,height:12,background:"#eee",borderRadius:3,overflow:"hidden"}}>
                  <div style={{width:`${v.pct}%`,height:"100%",background:bc,borderRadius:3}}/>
                </div>
                <div style={{fontSize:10,color:"#1a56c4",fontWeight:"bold",width:60,flexShrink:0}}>{v.val} cargues</div>
                <div style={{fontSize:11,fontWeight:900,color:"#b5c832",width:36,flexShrink:0}}>{v.pct}%</div>
              </div>
            );
          })}
          <div style={{marginTop:8,fontSize:10,color:"#666",borderTop:"1px solid #ddd",paddingTop:6}}>Total cargues del período: <strong>{totalDays}</strong></div>
        </div>
        {/* Observations */}
        <p style={{fontWeight:"bold",margin:"14px 0 5px"}}>7. OBSERVACIONES:</p>
        {(pdfObs || "Promedio de cargues por día: "+(days.length>0?(totalDays/days.length).toFixed(1):0)+" viajes.").split("\n").map((l,i)=>(
          <div key={i} style={{margin:"3px 0",fontSize:10}}>- {l}</div>
        ))}
        {/* Signature */}
        <div style={{borderTop:"1px dashed #aaa",marginTop:28,paddingTop:10}}>
          <div style={{marginBottom:4,fontSize:11}}>Realizo:</div>
          <img src={"data:image/png;base64,"} style={{height:55,objectFit:"contain",display:"block"}}/>
          <div style={{fontWeight:"bold"}}>RONALD JESUS ORTIZ</div>
        </div>
      </div>
    );
  };

  return(
    <div style={{minHeight:"100vh",background:C.bg,color:C.text,fontFamily:"'Segoe UI',Arial,sans-serif",paddingBottom:80}}>
      <style>{`*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}input[type=date]::-webkit-calendar-picker-indicator{filter:invert(1);}.tap:active{transform:scale(0.96);opacity:0.85;}input::placeholder,textarea::placeholder{color:#7c8099;}`}</style>

      {/* PDF Preview (off-screen for capture) */}
      {showPdfPreview && (
        <div style={{position:"fixed",left:"-9999px",top:0,zIndex:-1,background:"#fff"}}>
          <PdfPreview/>
        </div>
      )}

      {/* Generating overlay */}
      {generatingPdf && (
        <div style={{position:"fixed",inset:0,background:"#000b",zIndex:600,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:16}}>
          <div style={{width:48,height:48,border:`4px solid ${C.border}`,borderTop:`4px solid ${C.blue}`,borderRadius:"50%",animation:"spin 0.8s linear infinite"}}/>
          <div style={{color:"#fff",fontWeight:700,fontSize:15}}>Generando PDF...</div>
        </div>
      )}

      {/* Full screen PDF preview modal for iPhone Safari */}
      {showPdfModal && (
        <div style={{position:"fixed",inset:0,background:"#fff",zIndex:700,overflowY:"auto"}}>
          {/* Toolbar */}
          <div style={{position:"sticky",top:0,background:"#1a56c4",padding:"10px 14px",display:"flex",alignItems:"center",justifyContent:"space-between",zIndex:10,boxShadow:"0 2px 8px #0004"}}>
            <div style={{color:"#fff",fontWeight:700,fontSize:14}}>📄 Vista Previa Informe</div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={async()=>{setShowPdfModal(false);await new Promise(r=>setTimeout(r,100));setShowPdfPreview(true);await new Promise(r=>setTimeout(r,400));setGeneratingPdf(true);try{const el=pdfRef.current;if(!el)return;const canvas=await html2canvas(el,{scale:2,useCORS:true,allowTaint:true,backgroundColor:"#ffffff",logging:false});const imgData=canvas.toDataURL("image/png");const pdf=new jsPDF({orientation:"portrait",unit:"mm",format:"a4"});const pdfW=pdf.internal.pageSize.getWidth();const pdfH=pdf.internal.pageSize.getHeight();const imgW=canvas.width;const imgH=canvas.height;const ratio=pdfW/imgW;const scaledH=imgH*ratio;let y=0;let remaining=scaledH;while(remaining>0){const pageH=Math.min(pdfH,remaining);pdf.addImage(imgData,"PNG",0,-y,pdfW,scaledH);remaining-=pdfH;y+=pdfH;if(remaining>0)pdf.addPage();}pdf.save("Informe_Canaven_"+pdfFrom+"_"+pdfTo+".pdf");}catch(e){alert("Error: "+e.message);}setGeneratingPdf(false);setShowPdfPreview(false);}}
                style={{background:"#fff",color:"#1a56c4",border:"none",borderRadius:7,padding:"7px 12px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
                💾 Descargar PDF
              </button>
              <button onClick={()=>setShowPdfModal(false)}
                style={{background:"transparent",color:"#fff",border:"1px solid #ffffff55",borderRadius:7,padding:"7px 12px",fontSize:12,fontWeight:700,cursor:"pointer"}}>
                ✕ Cerrar
              </button>
            </div>
          </div>
          {/* Hint for iPhone */}
          <div style={{background:"#f0f7ff",borderBottom:"1px solid #cce",padding:"8px 14px",fontSize:11,color:"#1a56c4",textAlign:"center"}}>
            📱 iPhone: toca <strong>Compartir 📤</strong> → <strong>"Imprimir"</strong> → pellizca → <strong>Compartir</strong> → <strong>Guardar en Archivos</strong>
          </div>
          {/* Report content */}
          <div style={{padding:"8px 0",background:"#f5f5f5",minHeight:"100vh"}}>
            <PdfPreview/>
          </div>
        </div>
      )}

      {/* Confirm Load Modal */}
      {confirmModal&&(
        <div style={{position:"fixed",inset:0,background:"#000a",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:16,padding:24,width:"100%",maxWidth:360}}>
            <div style={{fontSize:15,fontWeight:800,marginBottom:16}}>Confirmar Cargue — {confirmModal.plate}</div>
            {[["Fecha de cargue","fecha","date"],["No. Guía","guia","text"],["Volumen cargado","volumen","text"]].map(([lbl,key,type])=>(
              <div key={key} style={{marginBottom:12}}>
                <div style={{fontSize:11,color:C.muted,marginBottom:4}}>{lbl}</div>
                <input type={type} value={loadForm[key]} onChange={e=>setLoadForm(p=>({...p,[key]:e.target.value}))}
                  placeholder={key==="volumen"?"Ej: 30000 galones":""}
                  style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"9px 12px",color:C.text,fontSize:13,outline:"none"}}/>
              </div>
            ))}
            <div style={{display:"flex",gap:8,marginTop:16}}>
              <button onClick={()=>setConfirmModal(null)} style={{flex:1,background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:"11px 0",color:C.muted,cursor:"pointer",fontWeight:700,fontSize:13}}>Cancelar</button>
              <button onClick={confirmLoad} style={{flex:2,background:C.green,color:"#111",border:"none",borderRadius:10,padding:"11px 0",cursor:"pointer",fontWeight:700,fontSize:13}}>✓ Confirmar Cargue</button>
            </div>
          </div>
        </div>
      )}

      {/* Edit Vehicle Modal */}
      {editVehicle&&(
        <div style={{position:"fixed",inset:0,background:"#000a",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
          <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:16,padding:24,width:"100%",maxWidth:340}}>
            <div style={{fontSize:15,fontWeight:800,marginBottom:16}}>Editar Vehículo</div>
            <div style={{marginBottom:12}}>
              <div style={{fontSize:11,color:C.muted,marginBottom:4}}>Placa</div>
              <input value={editVehicle.newPlate} onChange={e=>setEditVehicle(p=>({...p,newPlate:e.target.value.toUpperCase()}))}
                style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"9px 12px",color:C.text,fontSize:14,outline:"none",textTransform:"uppercase"}}/>
            </div>
            <div style={{marginBottom:12}}>
              <div style={{fontSize:11,color:C.muted,marginBottom:4}}>Nombre del Propietario</div>
              <input value={editVehicle.owner} onChange={e=>setEditVehicle(p=>({...p,owner:e.target.value}))}
                placeholder="Nombre completo"
                style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"9px 12px",color:C.text,fontSize:13,outline:"none"}}/>
            </div>
            <div style={{display:"flex",gap:8,marginTop:16}}>
              <button onClick={()=>setEditVehicle(null)} style={{flex:1,background:C.surface,border:`1px solid ${C.border}`,borderRadius:10,padding:"11px 0",color:C.muted,cursor:"pointer",fontWeight:700,fontSize:13}}>Cancelar</button>
              <button onClick={saveEditVehicle} style={{flex:2,background:C.blue,color:"#fff",border:"none",borderRadius:10,padding:"11px 0",cursor:"pointer",fontWeight:700,fontSize:13}}>Guardar</button>
            </div>
          </div>
        </div>
      )}

      {/* HEADER */}
      <div style={{background:C.surface,borderBottom:`1px solid ${C.border}`,padding:"10px 14px",position:"sticky",top:0,zIndex:100}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <CanavenLogo/>
          <div style={{textAlign:"right"}}>
            <div style={{display:"flex",gap:6,justifyContent:"flex-end",alignItems:"center",marginBottom:2}}>
              <span style={{fontSize:9,color:isAdmin?C.blue:C.green,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.08em"}}>{isAdmin?"⚙️ Admin":"👁️ Visitante"}</span>
              <button onClick={()=>{sessionStorage.removeItem("canaven_role");setAuthed(false);setRole("");setPinInput("");}} style={{background:"transparent",border:`1px solid ${C.border}`,borderRadius:4,color:C.muted,fontSize:9,cursor:"pointer",padding:"1px 5px"}}>Salir</button>
            </div>
            <div style={{fontSize:9,color:syncing?C.orange:C.green,letterSpacing:"0.1em",textTransform:"uppercase",fontWeight:700}}>{syncing?"⏳ Guardando...":"☁️ Sincronizado"}</div>
            <div style={{fontSize:9,color:C.muted,marginTop:1}}>{(()=>{const d=new Date(selectedDate+"T12:00:00");return `${DAYS_ES[d.getDay()]} ${d.getDate()} ${MONTHS_ES[d.getMonth()]}`;})()}</div>
          </div>
        </div>
      </div>

      <div style={{padding:"14px",maxWidth:600,margin:"0 auto"}}>

        {/* ===== FLEET ===== */}
        {tab==="fleet"&&(
          <div>
            <div style={{marginBottom:14}}>
              <div style={{fontSize:16,fontWeight:700,marginBottom:2}}>Gestión de Flota</div>
              <div style={{fontSize:12,color:C.muted}}>{vehicles.filter(v=>v.available).length} disponibles · {vehicles.filter(v=>!v.available).length} no disponibles</div>
            </div>
            {isAdmin&&(
              <div style={{display:"flex",gap:8,marginBottom:14}}>
                <input id="new-plate-input" placeholder="Nueva placa" onKeyDown={e=>e.key==="Enter"&&addVehicle()}
                  style={{flex:1,background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:"11px 14px",color:C.text,fontSize:14,outline:"none",textTransform:"uppercase"}}/>
                <button onClick={addVehicle} className="tap" style={{background:C.blue,color:"#fff",border:"none",borderRadius:10,padding:"11px 22px",fontSize:18,fontWeight:700,cursor:"pointer"}}>+</button>
              </div>
            )}
            <div style={{display:"flex",flexDirection:"column",gap:8}}>
              {vehicles.map((v,idx)=>{
                const tot=vehicleTotals[v.plate]||{};
                return(
                  <div key={v.plate} style={{background:C.card,border:`1.5px solid ${v.available?C.green+"44":C.red+"33"}`,borderRadius:12,padding:"12px 14px",position:"relative"}}>
                    <div style={{position:"absolute",top:0,left:0,width:"100%",height:3,borderRadius:"12px 12px 0 0",background:v.available?`linear-gradient(90deg,${C.green},transparent)`:`linear-gradient(90deg,${C.red},transparent)`}}/>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                      <div style={{display:"flex",alignItems:"center",gap:8}}>
                        <span style={{fontSize:11,color:C.muted,fontWeight:700,minWidth:20}}>{idx+1}</span>
                        <div>
                          <div style={{fontSize:17,fontWeight:900,color:C.text,letterSpacing:"0.06em"}}>{v.plate}</div>
                          {v.owner&&<div style={{fontSize:11,color:C.muted,marginTop:1}}>👤 {v.owner}</div>}
                        </div>
                      </div>
                      <div style={{display:"flex",gap:6}}>
                        {isAdmin&&<button onClick={()=>setEditVehicle({plate:v.plate,newPlate:v.plate,owner:v.owner||""})} style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,color:C.muted,cursor:"pointer",fontSize:12,padding:"3px 8px"}}>✏️</button>}
                        {isAdmin&&<button onClick={()=>removeVehicle(v.plate)} style={{background:"transparent",border:"none",color:C.muted,fontSize:17,cursor:"pointer",padding:"2px 6px"}}>✕</button>}
                      </div>
                    </div>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:isAdmin&&!v.replacedBy?8:0}}>
                      {isAdmin?(
                        <button onClick={()=>!v.replacedBy&&toggleAvailability(v.plate)} className="tap"
                          style={{...badge(v.available),cursor:v.replacedBy?"default":"pointer",padding:"5px 12px",fontSize:11,opacity:v.replacedBy?0.6:1}}>
                          <span style={{width:6,height:6,borderRadius:"50%",background:v.available?C.green:C.red,display:"inline-block"}}/>
                          {v.replacedBy?`Reemplazado → ${v.replacedBy}`:v.available?"Disponible":"No Disponible"}
                        </button>
                      ):(
                        <span style={{...badge(v.available),padding:"5px 12px",fontSize:11}}>
                          <span style={{width:6,height:6,borderRadius:"50%",background:v.available?C.green:C.red,display:"inline-block"}}/>
                          {v.replacedBy?`→ ${v.replacedBy}`:v.available?"Disponible":"No Disponible"}
                        </span>
                      )}
                      <div style={{display:"flex",gap:12}}>
                        {[["📋",tot.scheduled||0,C.blue],["✅",tot.loaded||0,C.green]].map(([icon,val,color])=>(
                          <div key={icon} style={{textAlign:"center"}}><div style={{fontSize:14,fontWeight:800,color}}>{val}</div><div style={{fontSize:9,color:C.muted}}>{icon}</div></div>
                        ))}
                      </div>
                    </div>
                    {isAdmin&&!v.replacedBy&&(
                      <div style={{display:"flex",gap:6,marginTop:6}}>
                        <input value={replaceInput[v.plate]||""} onChange={e=>setReplaceInput(p=>({...p,[v.plate]:e.target.value}))} onKeyDown={e=>e.key==="Enter"&&applyReplacement(v.plate)}
                          placeholder="Placa reemplazo (opcional)"
                          style={{flex:1,background:C.surface,border:`1px solid ${C.border}`,borderRadius:7,padding:"7px 10px",color:C.text,fontSize:12,outline:"none",textTransform:"uppercase"}}/>
                        <button onClick={()=>applyReplacement(v.plate)} disabled={!(replaceInput[v.plate]||"").trim()} className="tap"
                          style={{background:(replaceInput[v.plate]||"").trim()?C.orange:C.border,color:"#fff",border:"none",borderRadius:7,padding:"7px 12px",fontSize:12,fontWeight:700,cursor:(replaceInput[v.plate]||"").trim()?"pointer":"not-allowed"}}>↔</button>
                      </div>
                    )}
                    {isAdmin&&v.replacedBy&&(
                      <button onClick={()=>clearReplacement(v.plate)} className="tap" style={{marginTop:6,background:"transparent",border:`1px solid ${C.border}`,borderRadius:7,padding:"5px 12px",color:C.muted,fontSize:11,cursor:"pointer",fontWeight:600}}>✕ Quitar reemplazo</button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* ===== SCHEDULE ===== */}
        {tab==="schedule"&&(
          <div>
            <div style={{marginBottom:12}}><div style={{fontSize:16,fontWeight:700,marginBottom:2}}>Programación Diaria</div><div style={{fontSize:12,color:C.muted}}>Selecciona vehículos disponibles</div></div>
            <input type="date" value={selectedDate} onChange={e=>setSelectedDate(e.target.value)} style={{width:"100%",background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:"11px 14px",color:C.text,fontSize:14,outline:"none",marginBottom:12}}/>
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"12px 14px",marginBottom:12,display:"flex"}}>
              {[["Programados",scheduleForDate.length,C.blue],["Cargados",scheduleForDate.filter(v=>v.loaded).length,C.green]].map(([label,val,color],i)=>(
                <div key={label} style={{flex:1,textAlign:"center",borderRight:i<1?`1px solid ${C.border}`:"none"}}>
                  <div style={{fontSize:20,fontWeight:800,color}}>{val}</div>
                  <div style={{fontSize:10,color:C.muted,textTransform:"uppercase",letterSpacing:"0.06em"}}>{label}</div>
                </div>
              ))}
            </div>
            {scheduleForDate.length>0&&(
              <div style={{display:"flex",gap:8,marginBottom:12}}>
                <button onClick={copyMessage} className="tap" style={{flex:1,background:C.card,color:C.text,border:`1px solid ${C.border}`,borderRadius:10,padding:"11px 0",fontSize:13,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>📋 Copiar</button>
                <button onClick={sendWhatsApp} className="tap" style={{flex:2,background:"#25D366",color:"#fff",border:"none",borderRadius:10,padding:"11px 0",fontSize:13,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="white"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347z"/><path d="M12 0C5.373 0 0 5.373 0 12c0 2.117.554 4.103 1.523 5.826L.057 23.854a.5.5 0 0 0 .612.612l6.029-1.466A11.945 11.945 0 0 0 12 24c6.627 0 12-5.373 12-12S18.627 0 12 0zm0 21.818a9.807 9.807 0 0 1-5.002-1.366l-.358-.213-3.718.904.923-3.616-.234-.372A9.808 9.808 0 0 1 2.182 12C2.182 6.57 6.57 2.182 12 2.182S21.818 6.57 21.818 12 17.43 21.818 12 21.818z"/></svg>
                  Enviar al Grupo
                </button>
              </div>
            )}
            {/* Selector */}
            {isAdmin&&(
              <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,marginBottom:12,overflow:"hidden"}}>
                <div style={{padding:"11px 14px",borderBottom:`1px solid ${C.border}`,display:"flex",justifyContent:"space-between",alignItems:"center"}}>
                  <div style={{fontSize:13,fontWeight:700}}>Disponibles <span style={{color:C.muted,fontWeight:400}}>({notYetScheduled.length})</span></div>
                  <div style={{display:"flex",gap:6}}>
                    <button onClick={selectAll} className="tap" style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"4px 10px",color:C.muted,cursor:"pointer",fontSize:11,fontWeight:600}}>Todo</button>
                    <button onClick={clearSelection} className="tap" style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:6,padding:"4px 10px",color:C.muted,cursor:"pointer",fontSize:11,fontWeight:600}}>Limpiar</button>
                  </div>
                </div>
                {vehicles.map((v,idx)=>{
                  const isSched=alreadyScheduled.includes(v.plate);
                  const isSel=selectedPlates.includes(v.plate);
                  const disabled=!v.available||isSched;
                  return(
                    <div key={v.plate} onClick={()=>!disabled&&toggleSelectPlate(v.plate)}
                      style={{display:"flex",alignItems:"center",gap:12,padding:"12px 14px",borderBottom:`1px solid ${C.border}`,background:isSel?C.blue+"22":isSched?C.green+"0a":"transparent",cursor:disabled?"not-allowed":"pointer",opacity:disabled&&!isSched?0.38:1}}>
                      <span style={{fontSize:11,color:C.muted,minWidth:20,textAlign:"right",fontWeight:700}}>{idx+1}</span>
                      <div style={{width:22,height:22,borderRadius:6,border:`2px solid ${isSel?C.blue:isSched?C.green:C.border}`,background:isSel?C.blue:isSched?C.green+"33":"transparent",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,color:"#fff",fontWeight:900,flexShrink:0}}>{isSel?"✓":isSched?"●":""}</div>
                      <div style={{flex:1}}>
                        <div style={{fontWeight:800,fontSize:16,letterSpacing:"0.05em"}}>{v.plate}</div>
                        {v.owner&&<div style={{fontSize:10,color:C.muted}}>👤 {v.owner}</div>}
                      </div>
                      {isSched?<span style={{...badge(true),fontSize:9}}>Prog.</span>:v.available?<span style={{...badge(true),fontSize:9}}>Disp.</span>:<span style={{...badge(false),fontSize:9}}>No Disp.</span>}
                    </div>
                  );
                })}
                <div style={{padding:"12px 14px",background:C.surface}}>
                  <button onClick={addSelectedToSchedule} disabled={!selectedPlates.length} className="tap"
                    style={{width:"100%",background:selectedPlates.length?C.blue:C.border,color:selectedPlates.length?"#fff":C.muted,border:"none",borderRadius:10,padding:"13px 0",fontSize:15,fontWeight:700,cursor:selectedPlates.length?"pointer":"not-allowed"}}>
                    {selectedPlates.length?`⚡ Programar ${selectedPlates.length} vehículo(s)`:"Selecciona vehículos"}
                  </button>
                </div>
              </div>
            )}
            {!isAdmin&&<div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",marginBottom:12,textAlign:"center"}}><div style={{fontSize:13,color:C.muted}}>👁️ Modo solo lectura</div></div>}
            {/* Scheduled list */}
            {scheduleForDate.length>0&&(
              <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
                <div style={{padding:"11px 14px",borderBottom:`1px solid ${C.border}`,fontSize:13,fontWeight:700}}>Programados hoy · {scheduleForDate.filter(v=>v.loaded).length}/{scheduleForDate.length} cargados</div>
                {scheduleForDate.map((v,idx)=>{
                  const veh=vehicles.find(x=>x.plate===v.plate)||{};
                  return(
                    <div key={v.plate} style={{padding:"13px 14px",borderBottom:`1px solid ${C.border}`,background:v.loaded?C.green+"0d":"transparent"}}>
                      <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:8}}>
                        <span style={{fontSize:11,color:C.muted,fontWeight:700,minWidth:20}}>{idx+1}</span>
                        <div style={{width:8,height:8,borderRadius:"50%",background:v.loaded?C.green:C.orange,boxShadow:v.loaded?`0 0 7px ${C.green}`:`0 0 7px ${C.orange}`,flexShrink:0}}/>
                        <div style={{flex:1}}>
                          <div style={{fontWeight:900,fontSize:17,letterSpacing:"0.05em"}}>{v.plate}</div>
                          {veh.owner&&<div style={{fontSize:10,color:C.muted}}>👤 {veh.owner}</div>}
                        </div>
                        {isAdmin&&<button onClick={()=>removeFromSchedule(v.plate)} className="tap" style={{background:"transparent",border:`1px solid ${C.border}`,borderRadius:6,color:C.muted,cursor:"pointer",fontSize:11,padding:"3px 8px",fontWeight:600}}>Quitar</button>}
                      </div>
                      {/* Cargue details if loaded */}
                      {v.loaded&&(
                        <div style={{background:C.surface,borderRadius:8,padding:"8px 10px",marginBottom:8,fontSize:11,color:C.muted,display:"flex",gap:12,flexWrap:"wrap"}}>
                          {v.loadDate&&<span>📅 {v.loadDate}</span>}
                          {v.guia&&<span>📋 Guía: <strong style={{color:C.text}}>{v.guia}</strong></span>}
                          {v.volumen&&<span>🛢️ <strong style={{color:C.text}}>{v.volumen}</strong></span>}
                        </div>
                      )}
                      {/* Observaciones */}
                      <div style={{marginBottom:8}}>
                        {isAdmin?(
                          <input value={v.observaciones||""} onChange={e=>updateObservaciones(v.plate,e.target.value)}
                            placeholder="Observaciones..."
                            style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",color:C.text,fontSize:13,outline:"none"}}/>
                        ):v.observaciones?(
                          <div style={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 12px",color:C.muted,fontSize:13}}>📝 {v.observaciones}</div>
                        ):null}
                      </div>
                      {/* Confirm load button */}
                      {isAdmin?(
                        <button onClick={()=>openConfirmLoad(v.plate)} className="tap"
                          style={{width:"100%",background:v.loaded?C.green+"33":C.blue,color:v.loaded?C.green:"#fff",border:v.loaded?`1px solid ${C.green}`:"none",borderRadius:10,padding:"9px 10px",cursor:"pointer",fontWeight:700,fontSize:13}}>
                          {v.loaded?`✓ Cargado · ${v.loadedTime||""}`:"Confirmar Carga"}
                        </button>
                      ):(
                        <div style={{textAlign:"center",background:v.loaded?C.green+"22":C.surface,border:`1px solid ${v.loaded?C.green:C.border}`,borderRadius:10,padding:"9px",color:v.loaded?C.green:C.muted,fontWeight:700,fontSize:13}}>
                          {v.loaded?`✓ Cargado · ${v.loadedTime||""}`:"⏳ Programado"}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        )}

        {/* ===== REPORTS ===== */}
        {tab==="reports"&&(
          <div>
            <div style={{marginBottom:14}}><div style={{fontSize:16,fontWeight:700,marginBottom:2}}>Informes</div><div style={{fontSize:12,color:C.muted}}>Programación, cargas y análisis</div></div>
            <div style={{display:"flex",gap:8,marginBottom:14}}>
              <input type="date" value={selectedDate} onChange={e=>setSelectedDate(e.target.value)} style={{flex:1,background:C.card,border:`1px solid ${C.border}`,borderRadius:10,padding:"10px 12px",color:C.text,fontSize:13,outline:"none"}}/>
              {["weekly","monthly"].map(v=>(
                <button key={v} onClick={()=>setReportView(v)} className="tap"
                  style={{background:reportView===v?C.blue:C.card,color:reportView===v?"#fff":C.muted,border:`1px solid ${reportView===v?C.blue:C.border}`,borderRadius:10,padding:"10px 14px",cursor:"pointer",fontSize:12,fontWeight:700}}>
                  {v==="weekly"?"Semana":"Mes"}
                </button>
              ))}
            </div>
            {/* CSV */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",marginBottom:14}}>
              <div style={{fontSize:11,color:C.muted,marginBottom:10,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.07em"}}>⬇️ Descargar CSV de Cargues</div>
              <div style={{display:"flex",gap:8,marginBottom:10}}>
                <div style={{flex:1}}>
                  <div style={{fontSize:10,color:C.muted,marginBottom:4}}>Desde</div>
                  <input type="date" value={csvFrom} onChange={e=>setCsvFrom(e.target.value)}
                    style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",color:C.text,fontSize:12,outline:"none"}}/>
                </div>
                <div style={{flex:1}}>
                  <div style={{fontSize:10,color:C.muted,marginBottom:4}}>Hasta</div>
                  <input type="date" value={csvTo} onChange={e=>setCsvTo(e.target.value)}
                    style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",color:C.text,fontSize:12,outline:"none"}}/>
                </div>
              </div>
              <button onClick={downloadCSV} className="tap"
                style={{width:"100%",background:C.yellowGreen,color:"#111",border:"none",borderRadius:10,padding:"11px 0",fontSize:14,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
                <span style={{fontSize:18}}>📥</span> Descargar CSV
              </button>
            </div>
            {/* PDF */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",marginBottom:14}}>
              <div style={{fontSize:11,color:C.muted,marginBottom:10,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.07em"}}>📄 Generar Informe Operativo</div>
              <div style={{display:"flex",gap:8,marginBottom:10}}>
                <div style={{flex:1}}><div style={{fontSize:10,color:C.muted,marginBottom:4}}>Desde</div><input type="date" value={pdfFrom} onChange={e=>setPdfFrom(e.target.value)} style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",color:C.text,fontSize:12,outline:"none"}}/></div>
                <div style={{flex:1}}><div style={{fontSize:10,color:C.muted,marginBottom:4}}>Hasta</div><input type="date" value={pdfTo} onChange={e=>setPdfTo(e.target.value)} style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",color:C.text,fontSize:12,outline:"none"}}/></div>
              </div>
              <div style={{marginBottom:10}}>
                <div style={{fontSize:10,color:C.muted,marginBottom:4}}>Observaciones</div>
                <textarea value={pdfObs} onChange={e=>setPdfObs(e.target.value)} placeholder="Observaciones del informe..." rows={3}
                  style={{width:"100%",background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,padding:"8px 10px",color:C.text,fontSize:12,outline:"none",resize:"vertical",fontFamily:"inherit"}}/>
              </div>
              <div style={{display:"flex",gap:8}}>
                <button onClick={()=>setShowPdfModal(true)} className="tap"
                  style={{flex:1,background:"#1a56c4",color:"#fff",border:"none",borderRadius:10,padding:"12px 0",fontSize:13,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
                  <span style={{fontSize:16}}>👁️</span> Ver Informe
                </button>
                <button onClick={generatePDF} disabled={generatingPdf} className="tap"
                  style={{flex:1,background:generatingPdf?C.border:"#dc2626",color:"#fff",border:"none",borderRadius:10,padding:"12px 0",fontSize:13,fontWeight:700,cursor:generatingPdf?"not-allowed":"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}>
                  <span style={{fontSize:16}}>📄</span>{generatingPdf?"Generando...":"Descargar PDF"}
                </button>
              </div>
            </div>
            {/* KPIs */}
            <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:16}}>
              {[["Programados",reportData.reduce((s,d)=>s+d.programados,0),"📋",C.blue],["Cargados",reportData.reduce((s,d)=>s+d.cargados,0),"✅",C.green],
                ["Cumplimiento",reportData.reduce((s,d)=>s+d.programados,0)>0?Math.round(reportData.reduce((s,d)=>s+d.cargados,0)/reportData.reduce((s,d)=>s+d.programados,0)*100)+"%":"—","📈","#c084fc"],
                ["Días con cargue",reportData.filter(d=>d.cargados>0).length,"📅",C.yellowGreen]
              ].map(([label,val,icon,color])=>(
                <div key={label} style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:12,padding:"14px",position:"relative",overflow:"hidden"}}>
                  <div style={{position:"absolute",bottom:4,right:8,fontSize:32,opacity:0.07}}>{icon}</div>
                  <div style={{fontSize:24,fontWeight:900,color}}>{val}</div>
                  <div style={{fontSize:10,color:C.muted,marginTop:2,textTransform:"uppercase",letterSpacing:"0.07em"}}>{label}</div>
                </div>
              ))}
            </div>
            {/* Chart weekly/monthly */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:"14px 8px",marginBottom:16}}>
              <div style={{fontWeight:700,fontSize:13,marginBottom:12,paddingLeft:8}}>{reportView==="weekly"?`Semana del ${weekDates[0]}`:`${MONTHS_ES[currentMonth]} ${currentYear}`}</div>
              {reportData.length===0?<div style={{textAlign:"center",padding:"28px",color:C.muted,fontSize:13}}>Sin datos</div>:(
                <ResponsiveContainer width="100%" height={220}>
                  <BarChart data={reportData} margin={{top:0,right:4,left:-16,bottom:0}}>
                    <CartesianGrid strokeDasharray="3 3" stroke={C.border}/>
                    <XAxis dataKey="name" tick={{fill:C.muted,fontSize:11}} axisLine={{stroke:C.border}} tickLine={false}/>
                    <YAxis tick={{fill:C.muted,fontSize:10}} axisLine={false} tickLine={false}/>
                    <Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,color:C.text}}/>
                    <Legend wrapperStyle={{fontSize:11,color:C.muted}}/>
                    <Bar dataKey="programados" name="Prog." fill={C.blue} radius={[4,4,0,0]}/>
                    <Bar dataKey="cargados" name="Carg." fill={C.green} radius={[4,4,0,0]}/>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>
            {/* Monthly comparison */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:"14px 8px",marginBottom:16}}>
              <div style={{fontWeight:700,fontSize:13,marginBottom:4,paddingLeft:8}}>Comparativo Mensual</div>
              <div style={{fontSize:11,color:C.muted,marginBottom:12,paddingLeft:8}}>Total cargados por mes</div>
              {(()=>{
                const mmap={};
                Object.entries(schedules).forEach(([date,ds])=>{const d=new Date(date+"T12:00:00");const key=d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0");const label=MONTHS_ES[d.getMonth()].slice(0,3)+" "+d.getFullYear();if(!mmap[key])mmap[key]={label,total:0,prog:0};mmap[key].total+=ds.filter(v=>v.loaded).length;mmap[key].prog+=ds.length;});
                const arr=Object.entries(mmap).sort(([a],[b])=>a.localeCompare(b)).map(([,v])=>v);
                if(!arr.length)return<div style={{textAlign:"center",padding:"28px",color:C.muted,fontSize:13}}>Sin datos mensuales aún</div>;
                const data=arr.map(m=>({name:m.label.replace(" "," "),programados:m.prog,cargados:m.total}));
                const grandTotal=arr.reduce((s,m)=>s+m.total,0);
                return(<>
                  <ResponsiveContainer width="100%" height={240}>
                    <BarChart data={data} margin={{top:0,right:4,left:-16,bottom:20}}>
                      <CartesianGrid strokeDasharray="3 3" stroke={C.border}/>
                      <XAxis dataKey="name" tick={{fill:C.muted,fontSize:9}} axisLine={{stroke:C.border}} tickLine={false} angle={-35} textAnchor="end" interval={0}/>
                      <YAxis tick={{fill:C.muted,fontSize:10}} axisLine={false} tickLine={false}/>
                      <Tooltip contentStyle={{background:C.surface,border:`1px solid ${C.border}`,borderRadius:8,fontSize:12,color:C.text}}/>
                      <Legend wrapperStyle={{fontSize:11,color:C.muted}}/>
                      <Bar dataKey="programados" name="Programados" fill={C.blue} radius={[4,4,0,0]}/>
                      <Bar dataKey="cargados" name="Cargados" fill={C.green} radius={[4,4,0,0]}/>
                    </BarChart>
                  </ResponsiveContainer>
                  <div style={{marginTop:8,overflowX:"auto"}}>
                    <table style={{width:"100%",borderCollapse:"collapse",fontSize:12,fontFamily:"inherit"}}>
                      <thead><tr style={{background:C.surface}}>{["Mes","Prog.","Carg.","% del Total"].map(h=><th key={h} style={{padding:"8px 10px",textAlign:"left",fontSize:10,color:C.muted,textTransform:"uppercase",letterSpacing:"0.06em",borderBottom:`1px solid ${C.border}`}}>{h}</th>)}</tr></thead>
                      <tbody>{arr.map((m,i)=>{const pct=grandTotal>0?Math.round(m.total/grandTotal*100):0;return(<tr key={i} style={{borderBottom:`1px solid ${C.border}`,background:i%2===0?"transparent":C.surface+"44"}}>
                        <td style={{padding:"9px 10px",fontWeight:700,color:C.text}}>{m.label}</td>
                        <td style={{padding:"9px 10px",color:C.blue,fontWeight:600}}>{m.prog}</td>
                        <td style={{padding:"9px 10px",color:C.green,fontWeight:600}}>{m.total}</td>
                        <td style={{padding:"9px 10px"}}>
                          <div style={{display:"flex",alignItems:"center",gap:6}}>
                            <div style={{flex:1,height:5,background:C.border,borderRadius:3,overflow:"hidden"}}><div style={{width:`${pct}%`,height:"100%",background:pct>=25?C.green:pct>=10?C.yellowGreen:C.red,borderRadius:3}}/></div>
                            <span style={{fontSize:11,fontWeight:700,color:pct>=25?C.green:pct>=10?C.yellowGreen:C.muted,minWidth:30}}>{pct}%</span>
                          </div>
                        </td>
                      </tr>);})}</tbody>
                      <tfoot><tr style={{background:C.surface,borderTop:`2px solid ${C.border}`}}><td style={{padding:"9px 10px",fontWeight:800,color:C.text}}>TOTAL</td><td style={{padding:"9px 10px",fontWeight:800,color:C.blue}}>{arr.reduce((s,m)=>s+m.prog,0)}</td><td style={{padding:"9px 10px",fontWeight:800,color:C.green}}>{grandTotal}</td><td style={{padding:"9px 10px",fontWeight:800,color:C.yellowGreen}}>100%</td></tr></tfoot>
                    </table>
                  </div>
                </>);
              })()}
            </div>
            {/* Vehicle availability chart */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,padding:"14px",marginBottom:16}}>
              <div style={{fontWeight:700,fontSize:13,marginBottom:2}}>% Disponibilidad por Vehículo</div>
              <div style={{fontSize:11,color:C.muted,marginBottom:12}}>Participación de cargues en {MONTHS_ES[currentMonth]} {currentYear}</div>
              {(()=>{
                const monthTotal=Object.entries(schedules).filter(([date])=>{const d=new Date(date+"T12:00:00");return d.getMonth()===currentMonth&&d.getFullYear()===currentYear;}).reduce((sum,[,ds])=>sum+ds.filter(v=>v.loaded).length,0);
                const data=vehicles.map(v=>{const loaded=Object.entries(schedules).filter(([date])=>{const d=new Date(date+"T12:00:00");return d.getMonth()===currentMonth&&d.getFullYear()===currentYear;}).reduce((sum,[,ds])=>{const f=ds.find(s=>s.plate===v.plate);return sum+(f&&f.loaded?1:0);},0);return{plate:v.plate,val:loaded,pct:monthTotal>0?Math.round(loaded/monthTotal*100):0};}).filter(d=>d.val>0).sort((a,b)=>b.val-a.val);
                if(!data.length)return<div style={{textAlign:"center",padding:"20px",color:C.muted,fontSize:13}}>Sin datos para {MONTHS_ES[currentMonth]} {currentYear}</div>;
                return(<div style={{padding:"0 4px"}}>{data.map(d=>(
                  <div key={d.plate} style={{marginBottom:10}}>
                    <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                      <span style={{fontWeight:800,fontSize:13,color:C.text,letterSpacing:"0.05em"}}>{d.plate}</span>
                      <div style={{display:"flex",gap:10,alignItems:"center"}}>
                        <span style={{fontSize:12,color:C.green,fontWeight:700}}>{d.val} cargues</span>
                        <span style={{fontSize:13,fontWeight:900,color:C.yellowGreen,minWidth:36,textAlign:"right"}}>{d.pct}%</span>
                      </div>
                    </div>
                    <div style={{height:10,background:C.surface,borderRadius:5,overflow:"hidden",border:`1px solid ${C.border}`}}>
                      <div style={{width:`${d.pct}%`,height:"100%",borderRadius:5,background:d.pct>=20?C.green:d.pct>=10?C.yellowGreen:C.blue,transition:"width 0.4s"}}/>
                    </div>
                  </div>
                ))}<div style={{marginTop:12,padding:"8px 10px",background:C.surface,borderRadius:8,display:"flex",justifyContent:"space-between",fontSize:12}}><span style={{color:C.muted}}>Total cargues del mes:</span><span style={{fontWeight:800,color:C.green}}>{monthTotal}</span></div></div>);
              })()}
            </div>
            {/* Per vehicle table */}
            <div style={{background:C.card,border:`1px solid ${C.border}`,borderRadius:14,overflow:"hidden"}}>
              <div style={{padding:"11px 14px",borderBottom:`1px solid ${C.border}`,fontSize:13,fontWeight:700}}>Por Vehículo</div>
              {(()=>{
                const monthTotal=Object.entries(schedules).filter(([date])=>{const d=new Date(date+"T12:00:00");return d.getMonth()===currentMonth&&d.getFullYear()===currentYear;}).reduce((sum,[,ds])=>sum+ds.filter(v=>v.loaded).length,0);
                return vehicles.map((v,i)=>{
                  const t=vehicleTotals[v.plate]||{};
                  const vMonthLoaded=Object.entries(schedules).filter(([date])=>{const d=new Date(date+"T12:00:00");return d.getMonth()===currentMonth&&d.getFullYear()===currentYear;}).reduce((sum,[,ds])=>{const f=ds.find(s=>s.plate===v.plate);return sum+(f&&f.loaded?1:0);},0);
                  const eff=monthTotal>0?Math.round(vMonthLoaded/monthTotal*100):0;
                  return(
                    <div key={v.plate} style={{padding:"11px 14px",borderBottom:`1px solid ${C.border}`,background:i%2===0?"transparent":C.surface+"44"}}>
                      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:7}}>
                        <div style={{display:"flex",gap:8,alignItems:"center"}}>
                          <span style={{fontSize:10,color:C.muted,fontWeight:700}}>{i+1}</span>
                          <div><div style={{fontWeight:900,fontSize:15,color:C.yellowGreen,letterSpacing:"0.05em"}}>{v.plate}</div>{v.owner&&<div style={{fontSize:10,color:C.muted}}>👤 {v.owner}</div>}</div>
                        </div>
                        <span style={{...badge(v.available),fontSize:9}}>{v.available?"Disp.":"No Disp."}</span>
                      </div>
                      <div style={{display:"flex",gap:12,marginBottom:7}}>
                        {[["Prog",t.scheduled||0,C.blue],["Carg",t.loaded||0,C.green]].map(([lbl,val,color])=>(
                          <div key={lbl} style={{textAlign:"center"}}><div style={{fontSize:14,fontWeight:800,color}}>{val}</div><div style={{fontSize:9,color:C.muted}}>{lbl}</div></div>
                        ))}
                        <div style={{flex:1}}/>
                        <div style={{textAlign:"right"}}><div style={{fontSize:14,fontWeight:800,color:eff>=20?C.green:eff>=10?C.yellowGreen:C.muted}}>{eff}%</div><div style={{fontSize:9,color:C.muted}}>del mes</div></div>
                      </div>
                      <div style={{height:4,background:C.surface,borderRadius:3,overflow:"hidden"}}><div style={{width:`${eff}%`,height:"100%",background:eff>=20?C.green:eff>=10?C.yellowGreen:C.red,borderRadius:3}}/></div>
                    </div>
                  );
                });
              })()}
            </div>
          </div>
        )}
      </div>

      {/* BOTTOM NAV */}
      <div style={{position:"fixed",bottom:0,left:0,right:0,background:C.surface,borderTop:`1px solid ${C.border}`,display:"flex",zIndex:200}}>
        {TABS.map(t=>(
          <button key={t.id} onClick={()=>setTab(t.id)} className="tap"
            style={{flex:1,background:"transparent",border:"none",padding:"10px 4px 12px",cursor:"pointer",display:"flex",flexDirection:"column",alignItems:"center",gap:3}}>
            <div style={{fontSize:22}}>{t.icon}</div>
            <div style={{fontSize:10,fontWeight:700,color:tab===t.id?C.blue:C.muted,letterSpacing:"0.05em",textTransform:"uppercase"}}>{t.label}</div>
            {tab===t.id&&<div style={{width:24,height:3,borderRadius:2,background:C.blue,marginTop:1}}/>}
          </button>
        ))}
      </div>
    </div>
  );
}
